def verify_awards(guesses: dict[str, str], correct: dict[str, str], scores: dict[str, int], latest: dict[str, str]) -> dict[str, int]:
    def validate_vote(user: str, choice: str) -> bool:
        return isinstance(user, str) and isinstance(choice, str) and choice in {'a', 'b', 't'}
    def update_score(user: str, choice: str, scores: dict[str, int]) -> dict[str, int]:
        scores = dict(scores)
        scores[user] = scores.get(user, 0)
        if choice == 'a':
            scores[user] = scores[user] + 100
        elif choice == 'b':
            scores[user] = scores[user] + 50
        return scores

    new_scores = dict(scores)
    wrong = set()
    unchanged = set()
    changed = set()

    for user, choice in latest.items():
        if isinstance(user, bool) or isinstance(choice, bool) or not validate_vote(user, choice) or user not in correct:
            raise TypeError(f'Vote by {user} is not valid')
        expected = correct[user]
        if choice == expected:
            new_scores = update_score(user, choice, new_scores)
            changed.add(user)
        elif choice != expected:
            wrong.add(user)
            unchanged.add(user)
        if choice != latest.get(user, ''):
            changed.add(user)
        if choice == latest.get(user, ''):
            unchanged.add(user)

    return new_scores.copy()
